```php
<?php

function generateRandomPassword($length) {
    // Define the character sets for uppercase, lowercase, digits, and symbols
    $uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    $lowercase = 'abcdefghijklmnopqrstuvwxyz';
    $digits = '0123456789';
    $symbols = '!@#$%^&*()';

    // Combine all character sets into one string
    $allChars = $uppercase . $lowercase . $digits . $symbols;

    if ($length < 4) { // Ensure the password has at least 4 characters to avoid common patterns
        return "Password length should be at least 4 characters.";
    }

    // Generate random passwords until we get one with the required length
    while (true) {
        // Shuffle the combined character set
        $randomIndex = array_rand(str_split($allChars));

        // Convert the index back to the desired length
        $password = '';
        for ($i = 0; $i < $length; $i++) {
            $password .= substr($allChars, $randomIndex + $i * strlen($allChars) / $length, 1);
        }

        // Check if the generated password meets our criteria
        if (strlen($password) == $length && preg_match('/^[A-Za-z\d\s\!\@\#\$\%\^\&\*\(\)\_\-\+\=\{\}\[\]\,\:\<\>\?\'\"\\\/\\\[\]$/', $password)) {
            break;
        }
    }

    return $password;
}

// Example usage:
$length = 12; // Change this value to adjust the password length
$password = generateRandomPassword($length);

echo "Generated Password: " . $password;

?>
```

